functions.read:
def read(path: Path) -> dict:
    value = json.loads(path.read_text(encoding="utf-8"))
    if not isinstance(value, dict):
        raise ValueError("expected JSON object: " + str(path))
    return value

functions.status:
def status(value: str, **details: object) -> None:
    atomic(STATUS, {
        "at_utc": datetime.now(timezone.utc).isoformat(),
        "status": value,
        "baseline_completed_cycles": BASELINE_CYCLES,
        "campaign_start_raw": START_RAW,
        "campaign_target_days": TARGET_DAYS,
        "game_sdk_obs_calls": 0,
        **details,
    }, replace=True)

functions.next_sequence:
def next_sequence() -> int:
    sequence = read(NEXT).get("next_sequence")
    if type(sequence) is not int or sequence < 3:
        raise ValueError("P08 SDK has no valid fresh sequence")
    return sequence

functions.publish_or_follow:
def publish_or_follow(sequence: int) -> str:
    request = {"sequence": sequence, "command": "full_loop", "arguments": {"max_turns": 30}}
    inbox = request_path(sequence, INBOX)
    outbox = request_path(sequence, OUTBOX)
    if inbox.exists():
        existing = read(inbox)
        # Root's existing exact FULL6 carries its source explanation. Follow
        # the same command/sequence/arguments without rewriting that provenance.
        if request_maximum(sequence) != 30 or "tool" in existing:
            raise ValueError("next P08 control is occupied by a different request")
        return "following_existing_exact_control"
    if STOP.exists() or (N / "REQUEST-ADMISSION-CLOSED").exists() or (N / "EXIT-SDK").exists():
        raise RuntimeError("request admission closed before the next P08 control")
    if outbox.exists() or next_sequence() != sequence:
        raise ValueError("P08 SDK next sequence moved without an exact existing control")
    atomic(inbox, request)
    return "published_new_exact_control"
